"""第三次作业：动态规划与策略迭代。"""
def get_questions(p, f, ul):
    expectation = 'V<sup>π</sup>(s) = ∑<sub>a</sub> π(a|s) ∑<sub>s′,r</sub> p(s′,r|s,a)[r + γV<sup>π</sup>(s′)]'
    optimal = 'V<sub>k+1</sub>(s) = max<sub>a</sub> ∑<sub>s′,r</sub> p(s′,r|s,a)[r + γV<sub>k</sub>(s′)]'
    return [
    (3,1,'策略迭代的基本步骤','策略迭代包括哪些步骤？', ['策略评估','策略提升','价值迭代','动态规划'],(0,1),
    p('策略迭代（Policy Iteration）的核心是先评价当前策略，再根据评价结果改进策略。因此选 A、B。') + f('当前策略 π → 策略评估 → V<sup>π</sup> → 策略提升 → 新策略 π′ → 继续迭代') +
    '<h4>① 策略评估（Policy Evaluation）</h4>' + p('固定策略 π，计算一直按照该策略行动时，每个状态的期望长期回报。状态价值满足 Bellman 期望方程：') + f(expectation) + p('可以直接求解线性方程组，也可以反复进行期望更新，将价值评估到足够精确。') +
    '<h4>② 策略提升（Policy Improvement）</h4>' + p('对每个状态做一步前瞻，然后选择当前策略价值下最好的动作：') + f('Q<sup>π</sup>(s,a) = ∑<sub>s′,r</sub> p(s′,r|s,a)[r + γV<sup>π</sup>(s′)]<br>π′(s) ∈ arg max<sub>a</sub> Q<sup>π</sup>(s,a)') + p('这里先执行候选动作 a，之后按旧策略 π 行动。对所有状态进行贪心提升后，再重新评估新策略。价值迭代是另一种算法；动态规划是一类方法，都不是策略迭代的具体步骤。'),
    '策略提升定理与稳定的并列处理',p('在有限折扣 MDP、精确策略评估等标准条件下，贪心提升使 V<sup>π′</sup>(s) ≥ V<sup>π</sup>(s)。若策略对自身价值已经贪心，则满足 Bellman 最优方程，策略最优。') + p('实现时若多个动作并列最优，优先保留旧动作，或使用固定的并列处理规则，避免在同样好的策略之间反复切换。只有近似评估时，“策略没变”不应被无条件视为精确最优的证明。')),
    (3,2,'动态规划求解 MDP','下列哪些方法可用于求解马尔可夫决策过程？',['价值迭代','策略迭代','监督学习','分类算法'],(0,1),
    p('本题按经典动态规划求解 MDP 的语境，答案为 A、B。MDP 可表示为 (S,A,P,R,γ)，分别对应状态、动作、转移规律、奖励和折扣因子。已知环境模型后，可以通过规划寻找最优策略。') +
    '<h4>价值迭代（Value Iteration）</h4>' + p('直接反复应用 Bellman 最优更新：') + f(optimal) + p('在标准有限折扣 MDP 中，更新逐步逼近 V*，随后对最终价值函数做一步前瞻并取贪心动作，得到策略。') +
    '<h4>策略迭代（Policy Iteration）</h4>' + p('显式维护策略，交替进行策略评估与策略提升，直到策略稳定。') + p('监督学习通过带标签样本学习预测映射；分类算法处理离散标签预测。它们本身不是这里列举的经典 MDP 动态规划求解算法。'),
    '规划、学习与固定策略的联系',p('经典 DP 属于已知模型的规划方法；广义基于模型强化学习还包括从交互数据学习模型，再用模型规划。监督学习也可用于拟合转移模型或辅助价值估计，所以本题不能扩展成“监督学习永远不能帮助求解 MDP”。') + f('固定 π：V<sup>π</sup> = R<sup>π</sup> + γP<sup>π</sup>V<sup>π</sup><br>优化 π：V* = T*V*') + p('前者连接作业 2 的 MRP 策略评估；后者在每个状态比较动作，是控制问题。')),
    (3,3,'动态规划的适用条件','动态规划适用于什么样的问题？',['具有最优子结构和重叠子问题的问题','具有子问题但不一定有最优子结构的问题','只有具有最优子结构但没有重叠子问题的问题','只有具有重叠子问题但不具有最优子结构的问题'],0,
    p('按经典优化问题的教学表述，最合适的是 A：最优子结构与重叠子问题。') +
    '<h4>最优子结构（Optimal Substructure）</h4>' + p('原问题的最优解可以由适当子问题的最优解构成。例如在最短路径存在的标准问题中，若从 A 到 C 的最短路径经过 B，那么其中 A 到 B 的子路径也必须最短；否则替换成更短子路径，就能改进整条路径。') +
    '<h4>重叠子问题（Overlapping Subproblems）</h4>' + p('相同子问题反复出现，存储计算结果能避免重复工作。Fibonacci 递推 F(n)=F(n−1)+F(n−2) 中，计算 F(5) 会多次调用 F(3)、F(2)。记忆化或自底向上计算只需求每个子问题一次。') + f('拆解问题 → 求解子问题 → 保存结果 → 复用结果') + p('B 仅有子问题，不足以保证最优解能正确组合；C 缺少重叠，缓存优势不明显；D 只有重复计算，也不足以保证最优解的组合正确。'),
    'MDP 为什么适合动态规划？',p('Bellman 方程将当前决策分解为一步奖励与后继状态价值，体现最优子结构。不同路径与动作可能到达相同状态，因此同一个状态价值可被重复使用。') + p('“两个特征”是本题的典型优化问题判据，并非对所有 DP 的绝对定义。计数等非优化问题也能用 DP；Fibonacci 是展示重复子问题的例子，本身没有“最优解”。没有重叠时递推仍可能成立，只是存表未必带来额外收益。')),
    (3,4,'策略迭代与价值迭代','选出下列关于策略迭代与价值迭代的说法中错误的选项。',['价值迭代中不存在显式的策略','价值迭代中每步的策略评估需要收敛','策略迭代和价值迭代都是基于模型的强化学习算法','策略迭代通常比价值迭代收敛更慢'],(1,3),
    '<p class="note">本题要求选出错误选项。保留所给答案 B、D；A、C 采用课程中的典型算法表述，具体边界见下文。</p>' +
    ul('<b>A：按典型实现视为正确。</b> 价值迭代直接维护 V 并做 max 更新，通常不把策略作为独立迭代变量；但可随时提取或记录当前贪心策略，不能把“不存在”理解为绝对禁止。','<b>B：错误。</b> 价值迭代不需要先将每个中间策略评估到收敛，每轮直接进行 Bellman 最优更新。','<b>C：按课程语境视为正确。</b> 两者的经典形式都利用转移概率与奖励模型；更精确地说，它们是基于模型的规划方法。','<b>D：错误。</b> 不能笼统断言策略迭代通常收敛更慢，也不能反过来保证它总是更快。策略迭代往往外层改进轮数较少，但每轮评估可能很昂贵。') + f(optimal) +
    '<table><caption>两种经典方法的比较</caption><thead><tr><th>比较维度</th><th>策略迭代</th><th>价值迭代</th></tr></thead><tbody><tr><th>核心操作</th><td>评估 + 提升</td><td>Bellman 最优更新</td></tr><tr><th>显式策略</th><td>维护并改进</td><td>通常不单独维护，可提取</td></tr><tr><th>完整评估</th><td>经典精确版本需要</td><td>不需要</td></tr><tr><th>模型要求</th><td>需要</td><td>需要</td></tr><tr><th>计算代价</th><td>需计入评估成本</td><td>需计入所有更新轮次</td></tr></tbody></table>' + p('比较速度时应统一目标精度，并统计 Bellman 更新次数、线性求解成本或实际运行时间；外层轮数不是统一的计算单位。'),
    '修正策略迭代（Modified Policy Iteration）',p('策略评估不一定每次都做到完全收敛。修正策略迭代可以只执行若干次评估更新，就进行下一次提升，在经典策略迭代与价值迭代之间折中。') + p('因此“策略迭代需要完整评估”应限定为经典精确版本。对于有限折扣 MDP，价值迭代的 Bellman 算子具有 γ-压缩性；γ 接近 1 时，该误差界所保证的收缩通常更慢。')),
    (3,5,'异步动态规划','下列关于异步动态规划的说法中，哪些是正确的？',['异步动态规划需要同时更新所有状态的价值','异步动态规划不能减少计算复杂度','就地动态规划、优先级扫描、实时动态规划都属于异步动态规划','优先级扫描可利用贝尔曼误差的大小指导状态的选择'],(2,3),
    p('异步动态规划（Asynchronous DP）允许按需选择状态更新，而不是每轮都从同一份旧价值表计算全体状态的新值。因此答案为 C、D。') +
    ul('<b>A 错：</b>异步更新可以采用 S₂ → S₄ → S₁ → S₂ → S₅ 等顺序，不要求一轮覆盖全体状态。','<b>B 错：</b>合理的调度能够减少不必要的更新和实际计算量，但不保证在每个问题上都降低最坏情况的渐近复杂度。','<b>C 对：</b>就地动态规划、优先级扫描和实时动态规划都是典型异步方法。','<b>D 对：</b>可用 Bellman 残差的大小决定优先更新哪些状态。') +
    '<h4>三种典型方法</h4>' + ul('<b>就地 DP（In-place DP）：</b>只保留一份价值表，一个状态更新后，其新值可立即参与后续状态的更新。','<b>优先级扫描（Prioritized Sweeping）：</b>优先处理残差较大或受价值变化影响较大的状态；更新后，利用前驱关系把影响继续传播。','<b>实时 DP（Real-Time DP）：</b>沿模拟或实际交互轨迹，集中更新访问到的状态，减少对无关区域的计算。') +
    '<h4>用 Bellman 残差设置优先级</h4>' + f('δ(s) = | max<sub>a</sub> [R(s,a) + γ∑<sub>s′</sub>P(s′|s,a)V(s′)] − V(s) |') + p('此处 R(s,a) 是一步期望奖励，δ 已取绝对值，因此非负。它比较当前价值与模型计算出的更新目标；差距越大，通常越值得优先更新。') + f('较大残差 → 较高优先级 → 更新价值 → 重新评估相关前驱的优先级'),
    '同步不是并行；异步也需要覆盖条件',p('同步与异步的区别在于更新读取哪一版价值、选择哪些状态，并不等于多线程与单线程之分。同步更新可以顺序计算，但所有状态都读取旧表；就地更新则能读取本轮刚得到的新值。') + p('在有限折扣 MDP 中，用最新可用价值做异步最优更新，若每个状态都被无限次更新，可保证标准收敛结论。若长期忽略某些状态，就不能无条件保证全状态最优。实时 DP 只集中于访问区域时，保证范围还取决于探索、初始化及任务假设。') + p('模型下的 Bellman 残差也不同于单条经验的 TD 误差：后者含采样噪声，不能简单视为同一个量。')),
    ]

RECAP = '''<section id="dp-recap"><div class="eyebrow">DYNAMIC PROGRAMMING / 复习卡</div><h2>动态规划：三组核心对应</h2><div class="concepts"><p><b>策略迭代</b><br>策略评估 + 策略提升</p><p><b>价值迭代</b><br>直接进行 Bellman 最优更新</p><p><b>异步 DP</b><br>按需选状态，利用最新价值</p></div><table><caption>作业 3 · 易考判断</caption><thead><tr><th>说法</th><th>判断与条件</th></tr></thead><tbody><tr><td>策略迭代包括策略评估和策略提升</td><td>对</td></tr><tr><td>价值迭代和策略迭代可用已知模型求解 MDP</td><td>对</td></tr><tr><td>最优子结构和重叠子问题是经典优化 DP 的典型特征</td><td>对</td></tr><tr><td>价值迭代每一步都需要完整策略评估</td><td>错</td></tr><tr><td>经典策略迭代与价值迭代均为基于模型的方法</td><td>对；更精确地称为规划方法</td></tr><tr><td>仅凭外层迭代次数就能比较总计算时间</td><td>错；还要计入每轮成本</td></tr><tr><td>策略迭代一定比价值迭代快或慢</td><td>错；没有这种无条件结论</td></tr><tr><td>异步 DP 必须同时更新所有状态</td><td>错；可以只选部分状态</td></tr><tr><td>就地 DP、优先级扫描、实时 DP 属于异步 DP</td><td>对</td></tr><tr><td>优先级扫描可利用 Bellman 残差指导状态选择</td><td>对</td></tr><tr><td>异步更新可以永远忽略状态而保证全状态最优</td><td>错；需要相应的覆盖与收敛条件</td></tr></tbody></table><p>延伸阅读：<a href="https://www.davidsilver.uk/wp-content/uploads/2020/03/DP.pdf">David Silver · Lecture 3: Planning by Dynamic Programming</a>，对照策略评估、策略提升、修正策略迭代及异步动态规划。</p></section>'''
